fn split_column_helper(
    v: &Value,
    separator: &Regex,
    rest: &[Spanned<String>],
    collapse_empty: bool,
    number: Option<usize>,
    head: Span,
) -> Vec<Value> {
    if let Ok(s) = v.coerce_str() {
        let split_result: Vec<_> = match number {
            Some(number) => separator
                .splitn(&s, number)
                .filter(|x| !(collapse_empty && x.is_empty()))
                .collect(),
            None => separator
                .split(&s)
                .filter(|x| !(collapse_empty && x.is_empty()))
                .collect(),
        };
        let positional: Vec<_> = rest.iter().map(|f| f.item.clone()).collect();

        // If they didn't provide column names, make up our own
        SubCommand::new().records_from_split_parts(&split_result, &positional, head)
    } else {
        SubCommand::new().split_mismatch_or_error(v, head)
    }
}

